import '../extensions/string_extensions.dart';

/// Templates for the files generated by `thunder feature`.
///
/// Every template receives the project [packageName] so the generated code
/// uses `package:` imports and compiles wherever the file lives.
class ConstStrings {
  // create singleton for ConstStrings
  static final ConstStrings instance = ConstStrings._internal();

  factory ConstStrings() => instance;

  ConstStrings._internal();

  /// Repository with one GET method that calls `ApiConstants.<feature>`.
  String repo(String featureName, {required String packageName}) {
    final className = featureName.toDartClassName();
    final endpoint = featureName.toDartIdentifier();

    return '''
import 'package:$packageName/core/networking/api_result.dart';
import 'package:$packageName/core/networking/base_client.dart';
import 'package:$packageName/core/networking/enums_networking.dart';
import 'package:$packageName/helper/constants/api_constants.dart';

class ${className}Repo {
  final DioHelper dioHelper;

  ${className}Repo(this.dioHelper);

  Future<ApiResult> get${className}Data({Map<String, dynamic>? queryParameters}) {
    return dioHelper.safeApiCall(
      ApiConstants.$endpoint,
      RequestType.get,
      queryParameters: queryParameters,
    );
  }
}
''';
  }

  /// GetX controller that loads the feature data from its repository.
  String controllerGetX(String featureName, {required String packageName}) {
    final className = featureName.toDartClassName();
    final snake = featureName.toSnakeCase();
    final repoField = '${className}Repo'.lowerCaseFirstLetter();

    return '''
import 'package:get/get.dart';

import 'package:$packageName/app/repositories/${snake}_repo.dart';
import 'package:$packageName/core/networking/api_result.dart';
import 'package:$packageName/core/networking/enums_networking.dart';

class ${className}Controller extends GetxController {
  final ${className}Repo $repoField;

  ${className}Controller({required this.$repoField});

  ApiResult apiResult = ApiResult();

  /// Loads the data of this feature from the API.
  Future<void> getData() async {
    apiResult = ApiResult(apiCallStatus: ApiCallStatus.loading);
    update();

    apiResult = await $repoField.get${className}Data();
    apiResult.handelRequest(
      success: (result) {
        // TODO: convert result.data to your model
      },
      error: (result) {
        // TODO: handle the error (result.message)
      },
    );

    update();
  }

  @override
  void onInit() {
    super.onInit();
    getData();
  }
}
''';
  }

  /// View connected to its controller with loading / error / data states.
  String viewGetX(String featureName, {required String packageName}) {
    final className = featureName.toDartClassName();
    final snake = featureName.toSnakeCase();
    final title = featureName.words
        .map((w) => w.substring(0, 1).toUpperCase() + w.substring(1))
        .join(' ');

    return '''
import 'package:flutter/material.dart';
import 'package:get/get.dart';

import 'package:$packageName/core/networking/enums_networking.dart';
import 'package:$packageName/helper/widgets/custom_widgets/custom_text.dart';

import '${snake}_controller.dart';

class ${className}View extends StatelessWidget {
  const ${className}View({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const CustomText(txt: '${title.escapeForDartString()}')),
      body: GetBuilder<${className}Controller>(
        builder: (controller) {
          final apiResult = controller.apiResult;
          return switch (apiResult.apiCallStatus) {
            ApiCallStatus.loading => const Center(child: CircularProgressIndicator()),
            ApiCallStatus.error => Center(
                child: CustomText(txt: apiResult.message ?? 'Something went wrong'),
              ),
            ApiCallStatus.empty => const Center(child: CustomText(txt: 'No data yet')),
            _ => const Center(child: CustomText(txt: '${title.escapeForDartString()}')),
          };
        },
      ),
    );
  }
}
''';
  }

  /// GitHub Actions workflow that builds a release APK on every push to the
  /// main branch and sends it to a Telegram chat.
  String buildApkFileWorkFlow() {
    return r'''
name: Build APK and send it to Telegram

on:
  push:
    branches: [main, master]
  workflow_dispatch:

jobs:
  build_apk:
    name: Build Flutter (Android APK)
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-java@v4
        with:
          distribution: temurin
          java-version: '17'
      - uses: subosito/flutter-action@v2
        with:
          channel: stable
          cache: true
      - run: flutter pub get
      - run: flutter build apk --release --split-per-abi
      - name: Send APK to Telegram
        uses: appleboy/telegram-action@master
        with:
          to: ${{ secrets.TELEGRAM_CHAT_ID }}
          token: ${{ secrets.TELEGRAM_BOT_TOKEN }}
          message: |
            New build of ${{ github.repository }}
            Commit: ${{ github.sha }}
          document: build/app/outputs/flutter-apk/app-arm64-v8a-release.apk
''';
  }
}
